// ═══ VECTOR API (incubator — --add-modules jdk.incubator.vector) ═══
// Process 8 floats simultaneously using SIMD:
import jdk.incubator.vector.*;

float[] prices = new float[1024];
float[] quantities = new float[1024];
float[] totals = new float[1024];

// Scalar loop: processes ONE element at a time
for (int i = 0; i < 1024; i++) {
    totals[i] = prices[i] * quantities[i];
}

// Vector API: processes 8 elements AT ONCE (AVX-256):
var species = FloatVector.SPECIES_256;  // 8 floats per vector
for (int i = 0; i < 1024; i += species.length()) {
    var vPrices = FloatVector.fromArray(species, prices, i);
    var vQuantities = FloatVector.fromArray(species, quantities, i);
    var vTotals = vPrices.mul(vQuantities);  // 8 multiplications in 1 instruction!
    vTotals.intoArray(totals, i);
}
// ~4-8x speedup for float/int bulk operations!

