// File: src/test/java/com/bank/java8/ModernApiTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class ModernApiTest {

    // Scalar equivalent of a SIMD lane-wise multiply-add (risk = qty * price).
    double[] riskPerPosition(int[] qty, double[] price) {
        double[] r = new double[qty.length];
        for (int i = 0; i < qty.length; i++) r[i] = qty[i] * price[i];   // vectorisable loop
        return r;
    }

    @Test
    void laneWiseRiskComputation() {
        double[] risk = riskPerPosition(new int[]{100, 50}, new double[]{2450.5, 3100.0});
        assertThat(risk).containsExactly(245050.0, 155000.0);
    }
}
